    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #357abd;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
"}

