arguments.file_text:
@page "/chat"
@namespace sv_560bee0ef412446c8c9f4ba51d3a370d.Components.Pages.Chat

@using sv_560bee0ef412446c8c9f4ba51d3a370d.Services

@rendermode InteractiveServer

@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     ActiveChannelId="_selectedChannel?.Id ?? 0"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "expanded")">
        @if (_selectedChannel is not null)
        {
            <MessageArea Channel="_selectedChannel"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];
    private int _messagesLoaded;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messagesLoaded = 0;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messagesLoaded = _messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        _channels = await ChatService.GetChannelsAsync(); // Refresh unread counts
        ComputeThreadReplyCounts();
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null) return;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messagesLoaded, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messagesLoaded += older.Count;
            ComputeThreadReplyCounts();
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var sent = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(sent);
        _messagesLoaded++;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;
        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        if (_threadReplyCounts.ContainsKey(_threadRootMessage.Id))
            _threadReplyCounts[_threadRootMessage.Id]++;
        else
            _threadReplyCounts[_threadRootMessage.Id] = 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messagesLoaded);
            ComputeThreadReplyCounts();
        }
    }

    private void ComputeThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    width: 55%;
    flex: 1;
    min-width: 0;
    transition: width 0.2s ease;
}

.chat-main.expanded {
    width: 80%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #888;
    font-size: 1.1rem;
}

@page "/chat"
@namespace sv_560bee0ef412446c8c9f4ba51d3a370d.Components.Pages.Chat

@using sv_560bee0ef412446c8c9f4ba51d3a370d.Services

@rendermode InteractiveServer

@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     ActiveChannelId="_selectedChannel?.Id ?? 0"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "expanded")">
        @if (_selectedChannel is not null)
        {
            <MessageArea Channel="_selectedChannel"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];
    private int _messagesLoaded;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messagesLoaded = 0;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messagesLoaded = _messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        _channels = await ChatService.GetChannelsAsync(); // Refresh unread counts
        ComputeThreadReplyCounts();
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null) return;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messagesLoaded, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messagesLoaded += older.Count;
            ComputeThreadReplyCounts();
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var sent = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(sent);
        _messagesLoaded++;
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;
        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        if (_threadReplyCounts.ContainsKey(_threadRootMessage.Id))
            _threadReplyCounts[_threadRootMessage.Id]++;
        else
            _threadReplyCounts[_threadRootMessage.Id] = 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messagesLoaded);
            ComputeThreadReplyCounts();
        }
    }

    private void ComputeThreadReplyCounts()
    {
        _threadReplyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    width: 55%;
    flex: 1;
    min-width: 0;
    transition: width 0.2s ease;
}

.chat-main.expanded {
    width: 80%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #888;
    font-size: 1.1rem;
}

